        if 'large' in k:
            processed_data[k] = v - processing_overhead % 10
        else:
            processed_data[k] = v + 5

    # Final calculation
    final_throughput = max(processed_data.values()) * 2 - cache_hits
    network_efficiency = final_throughput / len(packet_sequence)

