import itertools

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def calculate_prime_sum(limit):
    primes = []
    for num in range(2, limit):
        if is_prime(num):
            primes.append(num)
    return sum(primes[:5])

