def calculate_network_efficiency(node_set, connection_map, traffic_data):
    active_nodes = {node for node in node_set if node % 2 == 0}
    redundant_nodes = {node for node in node_set if node % 3 == 0}

    primary_connections = set()
    for conn in connection_map:
        if conn[0] in active_nodes and conn[1] in active_nodes:
            primary_connections.add(conn)

    # Distractor calculations that don't affect final result
    total_possible_connections = len(active_nodes) * (len(active_nodes) - 1)
    unused_nodes = node_set - active_nodes

    efficient_traffic = 0
    for node_pair, traffic in traffic_data.items():
        if node_pair in primary_connections:
            efficient_traffic += traffic

    # More distractor operations
    node_efficiency_ratio = len(active_nodes) / len(node_set) if node_set else 0
    backup_traffic_capacity = len(redundant_nodes) * 100

    result = efficient_traffic
    return result

