def update_results(data_map, temp_vals):
    config_settings = {'threshold': 45, 'multiplier': 3, 'offset': 17}
    base_value = 128
    dummy_calc = (base_value >> 2) ^ 0b1101

    interim_data = {}
    for key, val in data_map.items():
        if val % 2 == 0:
            interim_data[key] = val * config_settings['multiplier'] - config_settings['offset']
        else:
            interim_data[key] = val + config_settings['threshold']

    temp_modifier = 0
    for k in temp_vals:
        temp_modifier ^= k

    unused_buffer = [i**2 for i in range(8, 15)]
    buffer_sum = sum(unused_buffer)

    final_computation = 0
    for item in interim_data.values():
        if item > 50:
            final_computation += item
        else:
            final_computation -= item

    if buffer_sum > 500:
        final_computation *= 2

    return {'result': final_computation | temp_modifier, 'aux': dummy_calc}

