def calculate_final_amount(transactions):
    initial_balance = 1000
    fee_calculator = lambda amount: amount * 0.02 if amount > 500 else amount * 0.01

    for transaction in transactions:
        if transaction['type'] == 'deposit':
            initial_balance += transaction['amount']
        else:
            fee = fee_calculator(transaction['amount'])
            initial_balance -= (transaction['amount'] + fee)

    return round(initial_balance, 2)

